package net.civeira.phylax.bootstrap.install;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Installs the test seed {@code install/oidc-seed.yaml} as the external file of a local deployment,
 * so it overrides the secrets of the classpath {@code migration/seed/oidc-seed.yaml}.
 */
final class LocalSeed {
  static final String PATH = "migration/seed/oidc-seed.yaml";

  private static final String RESOURCE = "install/oidc-seed.yaml";

  private LocalSeed() {}

  static void install(Path externalLocation) {
    Path target = externalLocation.resolve(PATH);
    try (InputStream in =
        Thread.currentThread().getContextClassLoader().getResourceAsStream(RESOURCE)) {
      if (null == in) {
        throw new IllegalStateException("Missing test resource " + RESOURCE);
      }
      Files.createDirectories(target.getParent());
      Files.copy(in, target);
    } catch (IOException ex) {
      throw new UncheckedIOException(ex);
    }
  }
}
